    def sum_of_digits(n):
        if n < 0:
            n = -n
            return -digit_sum(n)
        return digit_sum(n)

    def digit_sum(n):
        total = 0
        while n > 0:
            total += n % 10
            n //= 10
        return total

    count = 0
    for number in arr:
        if sum_of_digits(number) > 0:
            count += 1
    return count

